#蓝 6  紫 9  棕 10  红13  绿 14 淡蓝 15  黄  17  青18 粉 20 橙 21  淡黄22 淡绿 23 淡橙 24 淡紫 30 淡粉31
# ============================================
# 控制器创建函数
# ============================================

def create_controller(name, size=1.0, shape_type="Circle", color=None, orientation=(0, 0, 0), parent=None):
    """
    创建控制器并设置颜色、方向和父级
    
    参数:
        name: 控制器名称
        size: 控制器大小
        shape_type: 控制器类型 (见 CTRL_SHAPES 字典的键)
        color: 颜色索引 (0-31)
        orientation: 旋转角度 (rx, ry, rz) 单位为度
        parent: 父级变换节点名称，None 表示无父级
    
    返回:
        创建的曲线名称
    """
    # 检查形状是否存在
    if shape_type not in CTRL_SHAPES:
        print(f"⚠️ 形状 '{shape_type}' 不存在，使用 'Circle'")
        shape_type = "Circle"
    
    # 获取形状点
    points = CTRL_SHAPES[shape_type]
    
    # 缩放点
    if size != 1.0:
        scaled_points = [(p[0] * size, p[1] * size, p[2] * size) for p in points]
    else:
        scaled_points = points
    
    # 如果已存在同名曲线，删除
    if cmds.objExists(name):
        cmds.delete(name)
    
    # 创建曲线（默认使用1次曲线，即线性）
    curve = cmds.curve(
        degree=1,
        point=scaled_points,
        name=name
    )
    
    # 重命名 shape 节点
    shapes = cmds.listRelatives(curve, shapes=True, fullPath=False)
    if shapes:
        shape_name = f"{name}Shape"
        # 如果 shape 节点已存在，先删除
        if cmds.objExists(shape_name):
            cmds.delete(shape_name)
        # 重命名 shape 节点
        try:
            cmds.rename(shapes[0], shape_name)
        except:
            pass  # 如果重命名失败，保持默认
    
    # 设置父级
    if parent is not None:
        # 检查父级是否存在
        if cmds.objExists(parent):
            cmds.parent(curve, parent)
        else:
            print(f"⚠️ 父级 '{parent}' 不存在，跳过父级设置")
    
    # 设置方向（旋转）
    if orientation != (0, 0, 0):
        cmds.rotate(orientation[0], orientation[1], orientation[2], curve, a=True)
        
        cmds.makeIdentity(curve,apply=True, t=1, r=1, s=1, n=0)
    
    # 设置颜色
    if color is not None:
        cmds.setAttr(curve + "Shape.overrideEnabled", 1)
        cmds.setAttr(curve + "Shape.overrideColor", color)
    
    return curve